(* /mnt/1tb_kingston/Tekmerion/.bench/hol-light/Library/rstc.ml *)

(* ========================================================================= *)
(* All you wanted to know about reflexive symmetric and transitive closures. *)
(* ========================================================================= *)

prioritize_num();;

let RULE_INDUCT_TAC =
  MATCH_MP_TAC o DISCH_ALL o SPEC_ALL o UNDISCH o SPEC_ALL;;

(* ------------------------------------------------------------------------- *)
(* Little lemmas about equivalent forms of symmetry and transitivity.        *)
(* ------------------------------------------------------------------------- *)

let SYM_ALT = prove
 (`!R:A->A->bool. (!x y. R x y ==> R y x) <=> (!x y. R x y <=> R y x)`,
  CHEAT_TAC);;

let TRANS_ALT = prove
 (`!(R:A->A->bool) (S:A->A->bool) U.
        (!x z. (?y. R x y /\ S y z) ==> U x z) <=>
        (!x y z. R x y /\ S y z ==> U x z)`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Reflexive closure                                                         *)
(* ------------------------------------------------------------------------- *)

let RC_RULES,RC_INDUCT,RC_CASES = new_inductive_definition
  `(!x y. R x y ==> RC R x y) /\
   (!x:A. RC R x x)`;;

let RC_INC = prove
 (`!(R:A->A->bool) x y. R x y ==> RC R x y`,
  CHEAT_TAC);;

let RC_REFL = prove
 (`!(R:A->A->bool) x. RC R x x`,
  CHEAT_TAC);;

let RC_EXPLICIT = prove
 (`!(R:A->A->bool) x y. RC R x y <=> R x y \/ (x = y)`,
  CHEAT_TAC);;

let RC_MONO = prove
 (`!(R:A->A->bool) S.
        (!x y. R x y ==> S x y) ==>
            (!x y. RC R x y ==> RC S x y)`,
  CHEAT_TAC);;

let RC_CLOSED = prove
 (`!R:A->A->bool. (RC R = R) <=> !x. R x x`,
  CHEAT_TAC);;

let RC_IDEMP = prove
 (`!R:A->A->bool. RC(RC R) = RC R`,
  CHEAT_TAC);;

let RC_SYM = prove
 (`!R:A->A->bool.
        (!x y. R x y ==> R y x) ==> (!x y. RC R x y ==> RC R y x)`,
  CHEAT_TAC);;

let RC_TRANS = prove
 (`!R:A->A->bool.
        (!x y z. R x y /\ R y z ==> R x z) ==>
        (!x y z. RC R x y /\ RC R y z ==> RC R x z)`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Symmetric closure                                                         *)
(* ------------------------------------------------------------------------- *)

let SC_RULES,SC_INDUCT,SC_CASES = new_inductive_definition
  `(!x y. R x y ==> SC R x y) /\
   (!x:A y. SC R x y ==> SC R y x)`;;

let SC_INC = prove
 (`!(R:A->A->bool) x y. R x y ==> SC R x y`,
  CHEAT_TAC);;

let SC_SYM = prove
 (`!(R:A->A->bool) x y. SC R x y ==> SC R y x`,
  CHEAT_TAC);;

let SC_EXPLICIT = prove
 (`!R:A->A->bool. SC(R) x y <=> R x y \/ R y x`,
  CHEAT_TAC);;

let SC_MONO = prove
 (`!(R:A->A->bool) S.
        (!x y. R x y ==> S x y) ==>
        (!x y. SC R x y ==> SC S x y)`,
  CHEAT_TAC);;

let SC_CLOSED = prove
 (`!R:A->A->bool. (SC R = R) <=> !x y. R x y ==> R y x`,
  CHEAT_TAC);;

let SC_IDEMP = prove
 (`!R:A->A->bool. SC(SC R) = SC R`,
  CHEAT_TAC);;

let SC_REFL = prove
 (`!R:A->A->bool. (!x. R x x) ==> (!x. SC R x x)`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Transitive closure                                                        *)
(* ------------------------------------------------------------------------- *)

let TC_RULES,TC_INDUCT,TC_CASES = new_inductive_definition
   `(!x y. R x y ==> TC R x y) /\
    (!(x:A) y z. TC R x y /\ TC R y z ==> TC R x z)`;;

let TC_INC = prove
 (`!(R:A->A->bool) x y. R x y ==> TC R x y`,
  CHEAT_TAC);;

let TC_TRANS = prove
 (`!(R:A->A->bool) x y z. TC R x y /\ TC R y z ==> TC R x z`,
  CHEAT_TAC);;

let TC_MONO = prove
 (`!(R:A->A->bool) S.
        (!x y. R x y ==> S x y) ==>
        (!x y. TC R x y ==> TC S x y)`,
  CHEAT_TAC);;

let TC_CLOSED = prove
 (`!R:A->A->bool. (TC R = R) <=> !x y z. R x y /\ R y z ==> R x z`,
  CHEAT_TAC);;

let TC_IDEMP = prove
 (`!R:A->A->bool. TC(TC R) = TC R`,
  CHEAT_TAC);;

let TC_REFL = prove
 (`!R:A->A->bool. (!x. R x x) ==> (!x. TC R x x)`,
  CHEAT_TAC);;

let TC_SYM = prove
 (`!R:A->A->bool. (!x y. R x y ==> R y x) ==> (!x y. TC R x y ==> TC R y x)`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Commutativity properties of the three basic closure operations            *)
(* ------------------------------------------------------------------------- *)

let RC_SC = prove
 (`!R:A->A->bool. RC(SC R) = SC(RC R)`,
  CHEAT_TAC);;

let SC_RC = prove
 (`!R:A->A->bool. SC(RC R) = RC(SC R)`,
  CHEAT_TAC);;

let RC_TC = prove
 (`!R:A->A->bool. RC(TC R) = TC(RC R)`,
  CHEAT_TAC);;

let TC_RC = prove
 (`!R:A->A->bool. TC(RC R) = RC(TC R)`,
  CHEAT_TAC);;

let TC_SC = prove
 (`!(R:A->A->bool) x y. SC(TC R) x y ==> TC(SC R) x y`,
  CHEAT_TAC);;

let SC_TC = prove
 (`!(R:A->A->bool) x y. SC(TC R) x y ==> TC(SC R) x y`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Left and right variants of TC.                                            *)
(* ------------------------------------------------------------------------- *)

let TC_TRANS_L = prove
 (`!(R:A->A->bool) x y z. TC R x y /\ R y z ==> TC R x z`,
  CHEAT_TAC);;

let TC_TRANS_R = prove
 (`!(R:A->A->bool) x y z. R x y /\ TC R y z ==> TC R x z`,
  CHEAT_TAC);;

let TC_CASES_L = prove
 (`!(R:A->A->bool) x z. TC R x z <=> R x z \/ (?y. TC R x y /\ R y z)`,
  CHEAT_TAC);;

let TC_CASES_R = prove
 (`!(R:A->A->bool) x z. TC R x z <=> R x z \/ (?y. R x y /\ TC R y z)`,
  CHEAT_TAC);;

let TC_INDUCT_L = prove
 (`!(R:A->A->bool) P.
        (!x y. R x y ==> P x y) /\
        (!x y z. P x y /\ R y z ==> P x z) ==>
            (!x y. TC R x y ==> P x y)`,
  CHEAT_TAC);;

let TC_INDUCT_R = prove
 (`!(R:A->A->bool) P.
        (!x y. R x y ==> P x y) /\
        (!x z. (?y. R x y /\ P y z) ==> P x z) ==>
            (!x y. TC R x y ==> P x y)`,
  CHEAT_TAC);;

let WF_TC = prove
 (`!R:A->A->bool. WF(TC R) <=> WF(R)`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Reflexive symmetric closure                                               *)
(* ------------------------------------------------------------------------- *)

let RSC = new_definition
  `RSC(R:A->A->bool) = RC(SC R)`;;

let RSC_INC = prove
 (`!(R:A->A->bool) x y. R x y ==> RSC R x y`,
  CHEAT_TAC);;

let RSC_REFL = prove
 (`!(R:A->A->bool) x. RSC R x x`,
  CHEAT_TAC);;

let RSC_SYM = prove
 (`!(R:A->A->bool) x y. RSC R x y ==> RSC R y x`,
  CHEAT_TAC);;

let RSC_CASES = prove
 (`!(R:A->A->bool) x y. RSC R x y <=> (x = y) \/ R x y \/ R y x`,
  CHEAT_TAC);;

let RSC_INDUCT = prove
 (`!(R:A->A->bool) P.
        (!x y. R x y ==> P x y) /\
        (!x. P x x) /\
        (!x y. P x y ==> P y x)
        ==>  !x y. RSC R x y ==> P x y`,
  CHEAT_TAC);;

let RSC_MONO = prove
 (`!(R:A->A->bool) S.
        (!x y. R x y ==> S x y) ==>
        (!x y. RSC R x y ==> RSC S x y)`,
  CHEAT_TAC);;

let RSC_CLOSED = prove
 (`!R:A->A->bool. (RSC R = R) <=> (!x. R x x) /\ (!x y. R x y ==> R y x)`,
  CHEAT_TAC);;

let RSC_IDEMP = prove
 (`!R:A->A->bool. RSC(RSC R) = RSC R`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Reflexive transitive closure                                              *)
(* ------------------------------------------------------------------------- *)

let RTC = new_definition
  `RTC(R:A->A->bool) = RC(TC R)`;;

let RTC_INC = prove
 (`!(R:A->A->bool) x y. R x y ==> RTC R x y`,
  CHEAT_TAC);;

let RTC_REFL = prove
 (`!(R:A->A->bool) x. RTC R x x`,
  CHEAT_TAC);;

let RTC_TRANS = prove
 (`!(R:A->A->bool) x y z. RTC R x y /\ RTC R y z ==> RTC R x z`,
  CHEAT_TAC);;

let RTC_RULES = prove
 (`!(R:A->A->bool).
        (!x y. R x y ==> RTC R x y) /\
        (!x. RTC R x x) /\
        (!x y z. RTC R x y /\ RTC R y z ==> RTC R x z)`,
  CHEAT_TAC);;

let RTC_TRANS_L = prove
 (`!(R:A->A->bool) x y z. RTC R x y /\ R y z ==> RTC R x z`,
  CHEAT_TAC);;

let RTC_TRANS_R = prove
 (`!(R:A->A->bool) x y z. R x y /\ RTC R y z ==> RTC R x z`,
  CHEAT_TAC);;

let RTC_CASES = prove
 (`!(R:A->A->bool) x z. RTC R x z <=> (x = z) \/ ?y. RTC R x y /\ RTC R y z`,
  CHEAT_TAC);;

let RTC_CASES_L = prove
 (`!(R:A->A->bool) x z. RTC R x z <=> (x = z) \/ ?y. RTC R x y /\ R y z`,
  CHEAT_TAC);;

let RTC_CASES_R = prove
 (`!(R:A->A->bool) x z. RTC R x z <=> (x = z) \/ ?y. R x y /\ RTC R y z`,
  CHEAT_TAC);;

let RTC_INDUCT = prove
 (`!(R:A->A->bool) P.
        (!x y. R x y ==> P x y) /\
        (!x. P x x) /\
        (!x y z. P x y /\ P y z ==> P x z)
        ==> !x y. RTC R x y ==> P x y`,
  CHEAT_TAC);;

let RTC_INDUCT_L = prove
 (`!(R:A->A->bool) P.
        (!x. P x x) /\
        (!x y z. P x y /\ R y z ==> P x z)
        ==> !x y. RTC R x y ==> P x y`,
  CHEAT_TAC);;

let RTC_INDUCT_R = prove
 (`!(R:A->A->bool) P.
        (!x. P x x) /\
        (!x y z. R x y /\ P y z ==> P x z)
        ==> !x y. RTC R x y ==> P x y`,
  CHEAT_TAC);;

let RTC_MONO = prove
 (`!(R:A->A->bool) S.
        (!x y. R x y ==> S x y) ==>
        (!x y. RTC R x y ==> RTC S x y)`,
  CHEAT_TAC);;

let RTC_CLOSED = prove
 (`!R:A->A->bool. (RTC R = R) <=> (!x. R x x) /\
                                  (!x y z. R x y /\ R y z ==> R x z)`,
  CHEAT_TAC);;

let RTC_IDEMP = prove
 (`!R:A->A->bool. RTC(RTC R) = RTC R`,
  CHEAT_TAC);;

let RTC_SYM = prove
 (`!R:A->A->bool. (!x y. R x y ==> R y x) ==> (!x y. RTC R x y ==> RTC R y x)`,
  CHEAT_TAC);;

let RTC_STUTTER = prove
 (`RTC R = RTC (\x y. R x y /\ ~(x = y))`,
  CHEAT_TAC);;

let TC_RTC_CASES_L = prove
 (`TC R x z <=> ?y. RTC R x y /\ R y z`,
  CHEAT_TAC);;

let TC_RTC_CASES_R = prove
 (`!R x z. TC R x z <=> ?y. R x y /\ RTC R y z`,
  CHEAT_TAC);;

let TC_TC_RTC_CASES = prove
 (`!R x z. TC R x z <=> ?y. TC R x y /\ RTC R y z`,
  CHEAT_TAC);;

let TC_RTC_TC_CASES = prove
 (`!R x z. TC R x z <=> ?y. RTC R x y /\ TC R y z`,
  CHEAT_TAC);;

let RTC_NE_IMP_TC = prove
 (`!R x y. RTC R x y /\ ~(x = y) ==> TC R x y`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Symmetric transitive closure                                              *)
(* ------------------------------------------------------------------------- *)

let STC = new_definition
  `STC(R:A->A->bool) = TC(SC R)`;;

let STC_INC = prove
 (`!(R:A->A->bool) x y. R x y ==> STC R x y`,
  CHEAT_TAC);;

let STC_SYM = prove
 (`!(R:A->A->bool) x y. STC R x y ==> STC R y x`,
  CHEAT_TAC);;

let STC_TRANS = prove
 (`!(R:A->A->bool) x y z. STC R x y /\ STC R y z ==> STC R x z`,
  CHEAT_TAC);;

let STC_TRANS_L = prove
 (`!(R:A->A->bool) x y z. STC R x y /\ R y z ==> STC R x z`,
  CHEAT_TAC);;

let STC_TRANS_R = prove
 (`!(R:A->A->bool) x y z. R x y /\ STC R y z ==> STC R x z`,
  CHEAT_TAC);;

let STC_CASES = prove
 (`!(R:A->A->bool) x z. STC R x z <=> R x z \/ STC R z x \/
                                      ?y. STC R x y /\ STC R y z`,
  CHEAT_TAC);;

let STC_CASES_L = prove
 (`!(R:A->A->bool) x z. STC R x z <=> R x z \/ STC R z x \/
                                      ?y. STC R x y /\ R y z`,
  CHEAT_TAC);;

let STC_CASES_R = prove
 (`!(R:A->A->bool) x z. STC R x z <=> R x z \/ STC R z x \/
                                      ?y. R x y /\ STC R y z`,
  CHEAT_TAC);;

let STC_INDUCT = prove
 (`!(R:A->A->bool) P.
        (!x y. R x y ==> P x y) /\
        (!x y. P x y ==> P y x) /\
        (!x y z. P x y /\ P y z ==> P x z) ==>
                !x y. STC R x y ==> P x y`,
  CHEAT_TAC);;

let STC_MONO = prove
 (`!(R:A->A->bool) S.
        (!x y. R x y ==> S x y) ==>
        (!x y. STC R x y ==> STC S x y)`,
  CHEAT_TAC);;

let STC_CLOSED = prove
 (`!R:A->A->bool. (STC R = R) <=> (!x y. R x y ==> R y x) /\
                                  (!x y z. R x y /\ R y z ==> R x z)`,
  CHEAT_TAC);;

let STC_IDEMP = prove
 (`!R:A->A->bool. STC(STC R) = STC R`,
  CHEAT_TAC);;

let STC_REFL = prove
 (`!R:A->A->bool. (!x. R x x) ==> !x. STC R x x`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Reflexive symmetric transitive closure (smallest equivalence relation)    *)
(* ------------------------------------------------------------------------- *)

let RSTC = new_definition
  `RSTC(R:A->A->bool) = RC(TC(SC R))`;;

let RSTC_INC = prove
 (`!(R:A->A->bool) x y. R x y ==> RSTC R x y`,
  CHEAT_TAC);;

let RSTC_REFL = prove
 (`!(R:A->A->bool) x. RSTC R x x`,
  CHEAT_TAC);;

let RSTC_SYM = prove
 (`!(R:A->A->bool) x y. RSTC R x y ==> RSTC R y x`,
  CHEAT_TAC);;

let RSTC_TRANS = prove
 (`!(R:A->A->bool) x y z. RSTC R x y /\ RSTC R y z ==> RSTC R x z`,
  CHEAT_TAC);;

let RSTC_RULES = prove
 (`!(R:A->A->bool).
        (!x y. R x y ==> RSTC R x y) /\
        (!x. RSTC R x x) /\
        (!x y. RSTC R x y ==> RSTC R y x) /\
        (!x y z. RSTC R x y /\ RSTC R y z ==> RSTC R x z)`,
  CHEAT_TAC);;

let RSTC_TRANS_L = prove
 (`!(R:A->A->bool) x y z. RSTC R x y /\ R y z ==> RSTC R x z`,
  CHEAT_TAC);;

let RSTC_TRANS_R = prove
 (`!(R:A->A->bool) x y z. R x y /\ RSTC R y z ==> RSTC R x z`,
  CHEAT_TAC);;

let RSTC_CASES = prove
 (`!(R:A->A->bool) x z. RSTC R x z <=> (x = z) \/ R x z \/ RSTC R z x \/
                                       ?y. RSTC R x y /\ RSTC R y z`,
  CHEAT_TAC);;

let RSTC_CASES_L = prove
 (`!(R:A->A->bool) x z. RSTC R x z <=> (x = z) \/ R x z \/ RSTC R z x \/
                                     ?y. RSTC R x y /\ R y z`,
  CHEAT_TAC);;

let RSTC_CASES_R = prove
 (`!(R:A->A->bool) x z. RSTC R x z <=> (x = z) \/ R x z \/ RSTC R z x \/
                                       ?y. R x y /\ RSTC R y z`,
  CHEAT_TAC);;

let RSTC_INDUCT = prove
 (`!(R:A->A->bool) P.
        (!x y. R x y ==> P x y) /\
        (!x. P x x) /\
        (!x y. P x y ==> P y x) /\
        (!x y z. P x y /\ P y z ==> P x z)
        ==> !x y. RSTC R x y ==> P x y`,
  CHEAT_TAC);;

let RSTC_MONO = prove
 (`!(R:A->A->bool) S.
        (!x y. R x y ==> S x y) ==>
        (!x y. RSTC R x y ==> RSTC S x y)`,
  CHEAT_TAC);;

let RSTC_CLOSED = prove
 (`!R:A->A->bool. (RSTC R = R) <=> (!x. R x x) /\
                                   (!x y. R x y ==> R y x) /\
                                   (!x y z. R x y /\ R y z ==> R x z)`,
  CHEAT_TAC);;

let RSTC_IDEMP = prove
 (`!R:A->A->bool. RSTC(RSTC R) = RSTC R`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Finally, we prove the inclusion properties for composite closures         *)
(* ------------------------------------------------------------------------- *)

let RSC_INC_RC = prove
 (`!R:A->A->bool. !x y. RC R x y ==> RSC R x y`,
  CHEAT_TAC);;

let RSC_INC_SC = prove
 (`!R:A->A->bool. !x y. SC R x y ==> RSC R x y`,
  CHEAT_TAC);;

let RTC_INC_RC = prove
 (`!R:A->A->bool. !x y. RC R x y ==> RTC R x y`,
  CHEAT_TAC);;

let RTC_INC_TC = prove
 (`!R:A->A->bool. !x y. TC R x y ==> RTC R x y`,
  CHEAT_TAC);;

let STC_INC_SC = prove
 (`!R:A->A->bool. !x y. SC R x y ==> STC R x y`,
  CHEAT_TAC);;

let STC_INC_TC = prove
 (`!R:A->A->bool. !x y. TC R x y ==> STC R x y`,
  CHEAT_TAC);;

let RSTC_INC_RC = prove
 (`!R:A->A->bool. !x y. RC R x y ==> RSTC R x y`,
  CHEAT_TAC);;

let RSTC_INC_SC = prove
 (`!R:A->A->bool. !x y. SC R x y ==> RSTC R x y`,
  CHEAT_TAC);;

let RSTC_INC_TC = prove
 (`!R:A->A->bool. !x y. TC R x y ==> RSTC R x y`,
  CHEAT_TAC);;

let RSTC_INC_RSC = prove
 (`!R:A->A->bool. !x y. RSC R x y ==> RSTC R x y`,
  CHEAT_TAC);;

let RSTC_INC_RTC = prove
 (`!R:A->A->bool. !x y. RTC R x y ==> RSTC R x y`,
  CHEAT_TAC);;

let RSTC_INC_STC = prove
 (`!R:A->A->bool. !x y. STC R x y ==> RSTC R x y`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Handy things about reverse relations.                                     *)
(* ------------------------------------------------------------------------- *)

let INV = new_definition
  `INV R (x:A) (y:B) <=> R y x`;;

let RC_INV = prove
 (`RC(INV R) = INV(RC R)`,
  CHEAT_TAC);;

let SC_INV = prove
 (`SC(INV R) = INV(SC R)`,
  CHEAT_TAC);;

let SC_INV_STRONG = prove
 (`SC(INV R) = SC R`,
  CHEAT_TAC);;

let TC_INV = prove
 (`TC(INV R) = INV(TC R)`,
  CHEAT_TAC);;

let RSC_INV = prove
 (`RSC(INV R) = INV(RSC R)`,
  CHEAT_TAC);;

let RTC_INV = prove
 (`RTC(INV R) = INV(RTC R)`,
  CHEAT_TAC);;

let STC_INV = prove
 (`STC(INV R) = INV(STC R)`,
  CHEAT_TAC);;

let RSTC_INV = prove
 (`RSTC(INV R) = INV(RSTC R)`,
  CHEAT_TAC);;

(* ------------------------------------------------------------------------- *)
(* An iterative version of (R)TC.                                            *)
(* ------------------------------------------------------------------------- *)

let RELPOW = new_recursive_definition num_RECURSION
  `(RELPOW 0 (R:A->A->bool) x y <=> (x = y)) /\
   (RELPOW (SUC n) R x y <=> ?z. RELPOW n R x z /\ R z y)`;;

let RELPOW_R = prove
 (`(RELPOW 0 (R:A->A->bool) x y <=> (x = y)) /\
   (RELPOW (SUC n) R x y <=> ?z. R x z /\ RELPOW n R z y)`,
  CHEAT_TAC);;

let RELPOW_M = prove
 (`!m n x:A y. RELPOW (m + n) R x y <=> ?z. RELPOW m R x z /\ RELPOW n R z y`,
  CHEAT_TAC);;

let RTC_RELPOW = prove
 (`!R (x:A) y. RTC R x y <=> ?n. RELPOW n R x y`,
  CHEAT_TAC);;

let TC_RELPOW = prove
 (`!R (x:A) y. TC R x y <=> ?n. RELPOW (SUC n) R x y`,
  CHEAT_TAC);;

let RELPOW_SEQUENCE = prove
 (`!R n x y. RELPOW n R x y <=> ?f. (f(0) = x:A) /\ (f(n) = y) /\
                                    !i. i < n ==> R (f i) (f(SUC i))`,
  CHEAT_TAC);;
(* update digest *)
loaded_files := 
  let digest_bytes = [|98; 42; 182; 12; 42; 160; 217; 235; 24; 114; 98; 203; 72; 113; 192; 227|] in
  let digest = Bytes.init (Array.length digest_bytes) (fun i -> Char.chr digest_bytes.(i)) in
  ("rstc.ml", Bytes.to_string digest)::!loaded_files;;




(* /mnt/1tb_kingston/Tekmerion/.bench/hol-light/Library/bitsize.ml *)

(* ========================================================================= *)
(* Definition of "bitsize", how many bits are needed for a natural number.   *)
(* ========================================================================= *)

let bitsize = new_definition
 `bitsize n = minimal i. n < 2 EXP i`;;

let BITSIZE_0 = prove
 (`bitsize 0 = 0`,
  CHEAT_TAC);;

let BITSIZE_POW2 = prove
 (`!k. bitsize (2 EXP k) = k + 1`,
  CHEAT_TAC);;

let BITSIZE_1 = prove
 (`bitsize 1 = 1`,
  CHEAT_TAC);;

let BITSIZE_2 = prove
 (`bitsize 2 = 2`,
  CHEAT_TAC);;

let BITSIZE_LE = prove
 (`!n k. bitsize n <= k <=> n < 2 EXP k`,
  CHEAT_TAC);;

let BITSIZE = prove
 (`!n. n < 2 EXP bitsize n`,
  CHEAT_TAC);;

let BITSIZE_UNIQUE = prove
 (`!n k. bitsize n = k <=> n < 2 EXP k /\ !j. j < k ==> 2 EXP j <= n`,
  CHEAT_TAC);;

let BITSIZE_UNIQUE_ALT = prove
 (`!n k. bitsize n = k <=> !j. n < 2 EXP j <=> k <= j`,
  CHEAT_TAC);;

let BITSIZE_EQ_0 = prove
 (`!n. bitsize n = 0 <=> n = 0`,
  CHEAT_TAC);;

let BITSIZE_MONO = prove
 (`!m n. m <= n ==> bitsize m <= bitsize n`,
  CHEAT_TAC);;

let BITSIZE_MAX = prove
 (`!m n. bitsize(MAX m n) = MAX (bitsize m) (bitsize n)`,
  CHEAT_TAC);;

let BITSIZE_MIN = prove
 (`!m n. bitsize(MIN m n) = MIN (bitsize m) (bitsize n)`,
  CHEAT_TAC);;

let BITSIZE_MULT_LE = prove
 (`!m n. bitsize(m * n) <= bitsize m + bitsize n`,
  CHEAT_TAC);;

let BITSIZE_REV_EQ = prove
 (`!n. 2 EXP (bitsize n - 1) <= n <=> ~(n = 0)`,
  CHEAT_TAC);;

let BITSIZE_REV = prove
 (`!n. ~(n = 0) ==> 2 EXP (bitsize n - 1) <= n`,
  CHEAT_TAC);;

let BITSIZE_REV_EQ_ALT = prove
 (`!n. 2 EXP (bitsize n) <= 2 * n <=> ~(n = 0)`,
  CHEAT_TAC);;

let BITSIZE_REV_ALT = prove
 (`!n. ~(n = 0) ==> 2 EXP bitsize n <= 2 * n`,
  CHEAT_TAC);;

let LE_BITSIZE = prove
 (`!n k. k <= bitsize n <=> ~(k = 0) ==> 2 EXP (k - 1) <= n`,
  CHEAT_TAC);;

let LE_BITSIZE_ALT = prove
 (`!n k. k <= bitsize n <=> ~(k = 0) ==> 2 EXP k <= 2 * n`,
  CHEAT_TAC);;

let BITSIZE_UNIQUE_EQ = prove
 (`!n k. bitsize n = k <=>
         n < 2 EXP k /\ (~(k = 0) ==> 2 EXP k <= 2 * n)`,
  CHEAT_TAC);;

let BITSIZE_MULT = prove
 (`(!k n. bitsize (2 EXP k * n) = if n = 0 then 0 else k + bitsize n) /\
   (!k n. bitsize (n * 2 EXP k) = if n = 0 then 0 else bitsize n + k)`,
  CHEAT_TAC);;

let BITSIZE_MULT_ADD = prove
 (`(!k m n. ~(m = 0) /\ n < 2 EXP k
            ==> bitsize (2 EXP k * m + n) = k + bitsize m) /\
   (!k m n. ~(m = 0) /\ n < 2 EXP k
            ==> bitsize (m * 2 EXP k + n) = k + bitsize m) /\
   (!k m n. ~(m = 0) /\ n < 2 EXP k
            ==> bitsize (n + 2 EXP k * m) = k + bitsize m) /\
   (!k m n. ~(m = 0) /\ n < 2 EXP k
            ==> bitsize (n + m * 2 EXP k) = k + bitsize m)`,
  CHEAT_TAC);;

let BITSIZE_DIV = prove
 (`!n k. bitsize(n DIV 2 EXP k) = bitsize n - k`,
  CHEAT_TAC);;

let BITSIZE_CONV =
  let rec bitfun k n =
    if n =/ num_0 then k
    else bitfun (k + 1) (quo_num n num_2) in
  fun tm ->
   (match tm with
      Comb(Const("bitsize",_),ntm) when is_numeral ntm ->
        let ktm = mk_small_numeral(bitfun 0 (dest_numeral ntm)) in
        let th = SPECL [ntm;ktm] BITSIZE_UNIQUE_EQ in
        EQT_ELIM(CONV_RULE (RAND_CONV NUM_REDUCE_CONV) th)
    | _ -> failwith "BITSIZE_CONV");;
(* update digest *)
loaded_files := 
  let digest_bytes = [|25; 172; 116; 68; 74; 122; 252; 72; 132; 61; 225; 18; 25; 29; 22; 151|] in
  let digest = Bytes.init (Array.length digest_bytes) (fun i -> Char.chr digest_bytes.(i)) in
  ("bitsize.ml", Bytes.to_string digest)::!loaded_files;;




(* /mnt/1tb_kingston/Tekmerion/.bench/hol-light/Library/pocklington.ml *)

