let WEAKLY_VALID_COMPONENT_ZEROTOP_16 = prove
  (`weakly_valid_component(zerotop_16)`,
   CHEAT_TAC);;

add_weakly_valid_component_thms [WEAKLY_VALID_COMPONENT_ZEROTOP_16];;

