let arm_UMSUBL = define
 `arm_UMSUBL Rd Rn Rm Ra =
    \s. let n:int32 = read Rn (s:armstate)
        and m:int32 = read Rm s
        and a:int64 = read Ra s in
        let d:int64 = iword(&(val a) - &(val n) * &(val m)) in
