        CONV_RULE NUM_REDUCE_CONV o
        GEN_REWRITE_CONV I [arm_ST3])
      [`arm_ST3 [Rt1; Rt2; Rt3] Rn off 128 esize`;
       `arm_ST3 [Rt1; Rt2; Rt3] Rn off 64 esize`]);;

