   W7 = X7 :> zerotop_32 /\
   W8 = X8 :> zerotop_32 /\
   W9 = X9 :> zerotop_32 /\
   W10 = X10 :> zerotop_32 /\
   W11 = X11 :> zerotop_32 /\
   W12 = X12 :> zerotop_32 /\
   W13 = X13 :> zerotop_32 /\
   W14 = X14 :> zerotop_32 /\
   W15 = X15 :> zerotop_32 /\
   W16 = X16 :> zerotop_32 /\
   W17 = X17 :> zerotop_32 /\
   W18 = X18 :> zerotop_32 /\
   W19 = X19 :> zerotop_32 /\
   W20 = X20 :> zerotop_32 /\
   W21 = X21 :> zerotop_32 /\
   W22 = X22 :> zerotop_32 /\
   W23 = X23 :> zerotop_32 /\
   W24 = X24 :> zerotop_32 /\
   W25 = X25 :> zerotop_32 /\
   W26 = X26 :> zerotop_32 /\
   W27 = X27 :> zerotop_32 /\
   W28 = X28 :> zerotop_32 /\
   W29 = X29 :> zerotop_32 /\
   W30 = X30 :> zerotop_32`,
  CHEAT_TAC);;

let DREG_EXPAND_CLAUSES = prove
 (`D0 = Q0 :> zerotop_64 /\
   D1 = Q1 :> zerotop_64 /\
   D2 = Q2 :> zerotop_64 /\
   D3 = Q3 :> zerotop_64 /\
